// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle, and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const oldX = ball.x;
  const oldY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks: collision and bounce
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    // Simple tunneling check: if ball moved more than its radius + brick size, 
    // we might have tunneled. For this minimalist game, we check collision 
    // at start AND end of step, and if it's a high-speed move, we can 
    // approximate a swept check by checking the mid-point or using the AABB 
    // formed by oldPos and newPos.

    const isColliding = collides(ball, brick);
    const wasColliding = collides({ ...ball, x: oldX, y: oldY }, brick);

    if (isColliding || wasColliding) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      // Resolution: find the axis of minimum penetration
      const dx1 = (ball.x + ball.r) - brick.x;
      const dx2 = (brick.x + brick.w) - (ball.x - ball.r);
      const dy1 = (ball.y + ball.r) - brick.y;
      const dy2 = (brick.y + brick.h) - (ball.y - ball.r);
      const minPen = Math.min(dx1, dx2, dy1, dy2);

      if (minPen === dx1) {
        ball.vx = -Math.abs(ball.vx);
        ball.x = brick.x - ball.r;
      } else if (minPen === dx2) {
        ball.vx = Math.abs(ball.vx);
        ball.x = brick.x + brick.w + ball.r;
      } else if (minPen === dy1) {
        ball.vy = -Math.abs(ball.vy);
        ball.y = brick.y - ball.r;
      } else if (minPen === dy2) {
        ball.vy = Math.abs(ball.vy);
        ball.y = brick.y + brick.h + ball.r;
      }
      break; // Only one brick per step to avoid double-bounce artifacts
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

