// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle, and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Sub-stepping to prevent tunneling
  const speed = Math.sqrt(ball.vx ** 2 + ball.vy ** 2);
  const subSteps = Math.ceil((speed * dt) / (ball.r)) || 1;
  const subDt = dt / subSteps;

  for (let s = 0; s < subSteps; s++) {
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    // Bricks: collision and bounce
    for (const brick of state.bricks) {
      if (!brick.alive) continue;

      if (collides(ball, brick)) {
        const dx1 = (ball.x + ball.r) - brick.x;
        const dx2 = (brick.x + brick.w) - (ball.x - ball.r);
        const dy1 = (ball.y + ball.r) - brick.y;
        const dy2 = (brick.y + brick.h) - (ball.y - ball.r);

        const minX = Math.min(dx1, dx2);
        const minY = Math.min(dy1, dy2);
        const minPen = Math.min(minX, minY);

        // Corner hit: penetration on both axes is similar and ball is moving towards the brick
        if (Math.abs(minX - minY) < 2 && 
            ((dx1 < 2 && ball.vx > 0) || (dx2 < 2 && ball.vx < 0)) &&
            ((dy1 < 2 && ball.vy > 0) || (dy2 < 2 && ball.vy < 0))) {
          ball.vx = -ball.vx;
          ball.vy = -ball.vy;
          // Reposition simply
          if (dx1 < dx2) ball.x = brick.x - ball.r; else ball.x = brick.x + brick.w + ball.r;
          if (dy1 < dy2) ball.y = brick.y - ball.r; else ball.y = brick.y + brick.h + ball.r;
        } else if (minPen === dx1 && ball.vx > 0) {
          ball.vx = -Math.abs(ball.vx);
          ball.x = brick.x - ball.r;
        } else if (minPen === dx2 && ball.vx < 0) {
          ball.vx = Math.abs(ball.vx);
          ball.x = brick.x + brick.w + ball.r;
        } else if (minPen === dy1 && ball.vy > 0) {
          ball.vy = -Math.abs(ball.vy);
          ball.y = brick.y - ball.r;
        } else if (minPen === dy2 && ball.vy < 0) {
          ball.vy = Math.abs(ball.vy);
          ball.y = brick.y + brick.h + ball.r;
        } else {
          // Colliding but not moving towards the face (already bouncing away)
          // Just destroy the brick to avoid getting stuck
          brick.alive = false;
          state.combo += 1;
          state.score += scoreForBrick(brick, state.combo);
          continue;
        }

        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
        break; 
      }
    }
  }

  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

